ee:message.ee:set-payload:
%dw 2.0
output application/json
var fechaHoraColombia = (now() >> "America/Bogota") as String {
	format: "YYYY-MM-dd HH:mm:ss"
}
---
{
	id: vars.pqrResponse.databaseId,
	href: "/troubleTicket/" ++ (vars.pqrResponse.databaseId default ""),
	status: "acknowledged",
	creationDate: fechaHoraColombia,
	description: vars.initialPayload.ticket.pqr.description,
	characteristics: [
		{
			name: "CUN",
			value: vars.initialPayload.ticket.pqr.cunRelated
		},
		{
			name: "IsSon",
			value: vars.childPqr default false
		}
	]
}

