ee:variables.ee:set-variable:
%dw 2.0
output application/json
var botSystem = (vars.botSystemResponse.botSystem[0]- "_id")
var botChannel = (vars.botChannelResponse.botChannel[0] - "_id")
---
{
	"system": botSystem,
	"channel": botChannel,
	"user": vars.channelId default botChannel.Canal_Origen,
	"ip": vars.userIp,
	"sessionId": correlationId,
	"correlationId": correlationId
}

