ee:variables.ee:set-variable:
%dw 2.0
output application/json
var serviceAccount = (vars.serviceResponse.result[0].Bundle.Id_Servicio default vars.serviceActiveResponse.result[0].Id_Cuenta_Servicio)
var serviceTechnology = (vars.serviceResponse.result[0].Bundle.Tipo_Servicio default vars.serviceActiveResponse.result[0].Tecnologia)
var serviceName = (vars.serviceResponse.result[0].Bundle.Nombre default vars.serviceActiveResponse.result[0].Servicio)
var docType = (vars.serviceResponse.result[0].Cliente.Tipo_Documento default vars.serviceActiveResponse.result[0].Tipo_Documento)
var docNumber= (vars.serviceResponse.result[0].Cliente.Numero_Documento default vars.serviceActiveResponse.result[0].Numero_Identificacion)
---
{
	name: serviceName,
	account: serviceAccount,
	technology: serviceTechnology,
	docType: docType,
	docNumber: docNumber
}

