ee:variables.ee:set-variable:
%dw 2.0
output application/java
---
if(vars.sin_servicio == true)
{
	Numero_Identificacion: vars.initialPayload.ticket.customer.documentNumber,
	Tipo_Documento: vars.initialPayload.ticket.customer.documentType
}
else
{
	Numero_Identificacion: vars.service.docNumber,
	Tipo_Documento: vars.service.docType
}

