ee:variables.ee:set-variable:
%dw 2.0
output application/json
var requestDocTypeContact = vars.initialPayload.ticket.pqr.contact.documentType
var requestDocNumberContact = vars.initialPayload.ticket.pqr.contact.documentNumber
var matchedContact = ((vars.customerResponse.result[0].Contacto default []) filter ((item) -> (item.'Tipo_Documento' == requestDocTypeContact and item.'Numero_Documento' == requestDocNumberContact)) map ((item) -> {
	"email": item."Email_Contacto",
	"phone": if ( !isEmpty(item."Telefono_Contacto") ) item."Telefono_Contacto"
    else if ( !isEmpty(item."Movil_Contacto") ) item."Movil_Contacto"
    else if ( !isEmpty(item."Movil_Contacto2") ) item."Movil_Contacto2"
    else
      ""
}))[0] default {
}
---
{
	docType: requestDocTypeContact,
	docNumber: requestDocNumberContact,
	email: matchedContact.email default vars.initialPayload.ticket.pqr.contact.email,
	phone: matchedContact.phone default vars.initialPayload.ticket.pqr.contact.phone
}

%dw 2.0
output application/json
---
if ( !isEmpty(vars.botHomologatedRequest) ) {
	BOT_Peticion: vars.botHomologatedRequest
}
else
{
	causal: vars.initialPayload.ticket.pqr.failure.causal,
	clase: vars.initialPayload.ticket.pqr.failure.class,
	motivo: vars.initialPayload.ticket.pqr.failure.reason,
	sintoma: vars.initialPayload.ticket.pqr.failure.symptom,
	producto: vars.initialPayload.ticket.service.product,
	//estado: vars.initialPayload.ticket.pqr.state,
	//tecnologia: vars.service.technology
}

