%dw 2.0
import * from dw::core::Binaries
output multipart/form-data
var attachments = vars.initialPayload.ticket.pqr.attachment
---
{
	parts: {
		(attachments map (item, index) -> {
			attachmentId: {
				content: item.id
			},
			files: {
				content: fromBase64(item.file),
				headers: {
					"Content-Type": item.mimeType,
					"Content-Disposition": {
						"name": "files",
						"filename": item.name
					}
				}
			}
		})
	}
}
